using QuantForge.Core;namespace QuantForge.Core.ArchitectureTests;public sealed class StrategyDraftTests{[Fact]public void Draft_is_canonical_and_research_only(){var d=StrategyDraftRules.Create("s","ABC",new[]{new StrategyDraftParameter("z","2"),new StrategyDraftParameter("a","1")});Assert.True(d.ResearchOnly);Assert.False(d.CanSubmitOrders);Assert.Equal("a",d.Parameters[0].Name);StrategyDraftRules.Validate(d);}[Fact]public void Duplicate_parameter_names_fail_closed(){Assert.Throws<InvalidOperationException>(()=>StrategyDraftRules.Create("s","ABC",new[]{new StrategyDraftParameter("a","1"),new StrategyDraftParameter("a","2")}));}}
